how can I filter the segment_id array column I create in `t.mutate` and only keep the matching segment_id's from `tax` ?

```
import ibis
from ibis import _

ibis.options.interactive = True

t = ibis.memtable(
    {
        "user": ["a", "b"],
        "attribute": [
            [
                {"id": "attr1", "sv": 1},
                {"id": "attr2", "sv": 2},
                {"id": "attr3", "sv": 3},
            ],
            [{"id": "attr1", "sv": 1}, {"id": "attr5", "sv": None}],
        ],
    }
)

tax = ibis.memtable({"segment_id": ["attr1"], "segment_name": ["attribute 1"]})

def create_segment_id(row):
    return row["id"] + "_" + row["sv"].cast("string")

t.mutate(
    segment_id=_.attribute.map(create_segment_id)
    ).select(_.user, _.segment_id
             ).mutate(segment_id=_.segment_id.join(","))
    
```

I tried using partial and passing in tax.segment_id but I get `ValueError: The truth value of an Ibis expression is not defined`

```
from functools import partial


def create_segment_id(row, taxonomy):
    segment_id = row["id"] + "_" + row["sv"].cast("string")
    return segment_id if taxonomy.contains(segment_id) else None


create_segment_id_partial = partial(
    create_segment_id, taxonomy=tax.segment_id
)

t.mutate(
    segment_id=_.attribute.map(create_segment_id_partial
).select(_.user, _.segment_id
             ).mutate(segment_id=_.segment_id.join(","))

```

I can get what I want with `unnest()` and `agg` and `inner join` but that seems awfully wasteful. it would be better to filter at the array level before `unnest()`

```
t.mutate(
    segment_id=_.attribute.map(
        lambda row: row["id"].concat("_", row["sv"].cast("string"))
    )
).select(_.user, _.segment_id).unnest("segment_id"
                                      ).join(tax, _.segment_id == tax.segment_id
                                      ).select(_.user, _.segment_id
                                               ).group_by("user"
                                                    ).agg(v=_.segment_id.collect().join(","))
```

